<?php namespace App\Models; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Model; class Evidence extends Model{use HasFactory; protected $fillable=['company_id','opportunity_id','external_id','source_type','title','description','published_at','url','confidence','score_impact']; protected function casts():array{return ['published_at'=>'date','confidence'=>'integer','score_impact'=>'integer'];} public function company(){return $this->belongsTo(Company::class);} public function opportunity(){return $this->belongsTo(Opportunity::class);}}
